#include "exotic/cognition/agent_store.hpp"
#include "exotic/cognition/idle_cognition.hpp"
#include "exotic/cognition/operator_sessions.hpp"
#include <cassert>
#include <cstdio>
#include <string>
static void clean(const std::string&p){std::remove(p.c_str());std::remove((p+"-wal").c_str());std::remove((p+"-shm").c_str());}
int main(){const std::string path="exotic_agent_store_test.db";clean(path);{exotic::cognition::AgentStore store(path);store.initialize();store.save_identity({"free-agent-01","Nova","Persistent autonomous EXOTIC agent","geometric","hex-eye"});store.upsert_belief({"belief-1","Verification should precede external action",0.97,"ActionGate policy","2026-09-09T00:00:00Z"});store.upsert_goal({"goal-1","Investigate unresolved high-value questions",0.90,"self","active"});store.set_preference({"novelty",0.60});store.set_drive({"curiosity",0.40,0.75,0.10});store.append_reward({"reward-1","verification",0.50,"Correctly deferred unauthorized action","2026-09-09T00:00:00Z"});exotic::cognition::IdleCognitionScheduler idle(store);assert(idle.should_run(false));assert(idle.next_candidate().has_value());exotic::cognition::OperatorSessionManager sessions(store);auto session=sessions.create("local-operator","0123456789abcdef0123456789abcdef",1000,60);assert(sessions.validate(session.id,"0123456789abcdef0123456789abcdef",1010));sessions.revoke(session.id);assert(!sessions.validate(session.id,"0123456789abcdef0123456789abcdef",1010));}{exotic::cognition::AgentStore store(path);store.initialize();assert(store.load_identity().name=="Nova");assert(store.beliefs().size()>=1);bool found=false;for(const auto&g:store.goals())if(g.id=="goal-1"&&g.title=="Investigate unresolved high-value questions")found=true;assert(found);assert(store.preferences().size()>=1);assert(store.drives().size()>=1);assert(store.reward_total()>=0.50);}clean(path);return 0;}
